        "starterCode": "class Statistics:\n    def __init__(self, data):\n        self.data = sorted(data)\n\n    def count(self):\n        pass\n\n    def sum(self):\n        pass\n\n    def min(self):\n        pass\n\n    def max(self):\n        pass\n\n    def mean(self):\n        pass\n\n    def median(self):\n        pass\n",
        "solution": "class Statistics:\n    def __init__(self, data):\n        self.data = sorted(data)\n\n    def count(self):\n        return len(self.data)\n\n    def sum(self):\n        return sum(self.data)\n\n    def min(self):\n        return self.data[0]\n\n    def max(self):\n        return self.data[-1]\n\n    def mean(self):\n        return sum(self.data) / len(self.data)\n\n    def median(self):\n        n = len(self.data)\n        if n % 2 == 1:\n            return self.data[n // 2]\n        return (self.data[n // 2 - 1] + self.data[n // 2]) / 2\n",
